    request.session["preferences"] = {
        **existing,
        "servings": servings,
        "dietaryNeeds": dietary_needs.strip(),
        "adventureLevel": adventure_level,
        "mealPrepDays": meal_prep_days,
        "shoppingFrequency": shopping_frequency,
    }
